import exporters.ExporterPicker
import exporters.buildReport


fun main(args: Array<String>) {

    val rows = CsvReader().read("input.csv")

    val handler = Handler()
    val results = handler.handleProducts(rows)

    println(buildReport(results))

    val picker = ExporterPicker()

    print("Выберите формат (json, xml, txt): ")
    val format = readln().lowercase()

    val exporter = picker.getExporter(format)

    if (exporter != null) {
        val path = "output.$format"
        exporter.export(results, path)
        println("Результат сохранён в $path")
    } else {
        println("Неизвестный формат: $format")
    }
}
